    .find((b) => /^(Price|Standard \$|Classic \$\$|Specialty \$\$\$|Exclusive \$\$\$\$|Show all)$/.test(txt(b.innerText)));
  if (!btn) return { err: 'NO PRICE BUTTON' };
  btn.click(); await wait(600);
  const lb = [...document.querySelectorAll('[role=listbox][aria-label=Price]')].pop();
  if (!lb) return { err: 'NO LISTBOX' };
  const opts = [...lb.querySelectorAll('[role=option]')];
  const label = (o) => txt(o.querySelector('span')?.innerText || o.innerText);
  const offered = opts.map(label);
  const o = pick ? opts.find((x) => label(x) === pick) : null;
  if (!o) { lb.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); await wait(300);
    if (document.querySelector('[role=listbox][aria-label=Price]')) { btn.click(); await wait(300); } return { offered }; }
  (o.querySelector('button') || o).click(); await wait(900);
  return { offered };
};
const distribution = async (title) => {
  const s = await section(title); if (s.err || !s.scope) return { section: title, err: s.err || 'NO SCOPE' };
  const all = swatches(s.scope);
  const { offered, err } = await price(s.scope, null); if (err) return { section: title, err, total: all.count };
  const byTier = {};
  for (const tier of offered.filter((t) => t !== 'Show all')) {
    await price(s.scope, tier);
    const { count, groups, swatches: names } = swatches(s.scope);
    byTier[tier] = { count, groups, swatches: names };
  }
  await price(s.scope, 'Show all');
  const ranked = Object.values(byTier).reduce((n, t) => n + t.count, 0);
  return { section: title, total: all.count, totalGroups: all.groups, offered, ranked, byTier };
};
const pickOption = async (title, label) => {
  const s = await section(title); if (s.err || !s.scope) return { err: s.err || 'NO SCOPE' };
  const b = s.scope.querySelector(`button[aria-label="${label}"]`); if (!b) return { err: 'NO OPTION ' + label };
  b.scrollIntoView({ block: 'center' }); b.click(); await wait(4000); return 'picked ' + label;
};
return await distribution('Vessel Color');}
